function PrimaryButton({ children, onClick, href, className = "" }: { children: React.ReactNode; onClick?: () => void; href?: string; className?: string }) {
  const body = <span className={`btn-press inline-flex items-center justify-center gap-2 rounded-full bg-[#3a86ff] px-5 py-3 text-sm font-bold text-white shadow-[0_8px_28px_rgba(58,134,255,.2)] hover:bg-[#5a9bff] ${className}`}>{children}</span>;
  return href ? <Link href={href}>{body}</Link> : <button onClick={onClick}>{body}</button>;
}

function OutlineButton({ children, onClick, href, className = "" }: { children: React.ReactNode; onClick?: () => void; href?: string; className?: string }) {
  const body = <span className={`btn-press inline-flex items-center justify-center gap-2 rounded-full border border-white/15 bg-white/[.035] px-5 py-3 text-sm font-bold text-white hover:border-[#3a86ff]/70 hover:bg-[#3a86ff]/10 ${className}`}>{children}</span>;
  return href ? <Link href={href}>{body}</Link> : <button onClick={onClick}>{body}</button>;
}

function SiteHeader({ onJoin, locale: controlledLocale, onLocaleChange }: { onJoin?: () => void; locale?: Locale; onLocaleChange?: (locale: Locale) => void }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [headerLocale, setHeaderLocale] = useState<Locale>("en");
  const activeLocale = controlledLocale ?? headerLocale;
  const activeCopy = copy[activeLocale];
  const changeLocale = (value: Locale) => { setHeaderLocale(value); onLocaleChange?.(value); };
  const [location] = useLocation();
  return <header className="relative z-20 border-b border-white/[.07] bg-[#0d111a]/80 backdrop-blur-xl"><div className="mx-auto flex max-w-[1180px] items-center justify-between px-5 py-4 lg:px-8"><Logo /><nav className="hidden items-center gap-7 text-[12px] font-semibold text-slate-400 md:flex"><Link href="/explore" className={location === "/explore" ? "text-white" : "hover:text-white"}>{activeCopy.explore}</Link><Link href="/messages" className={location === "/messages" ? "text-white" : "hover:text-white"}>{activeCopy.messages}</Link><Link href="/safety" className={location === "/safety" ? "text-white" : "hover:text-white"}>{activeCopy.safety}</Link><Link href="/account" className={location === "/account" ? "text-white" : "hover:text-white"}>{proCopy[activeLocale].account}</Link></nav><div className="hidden items-center gap-3 md:flex"><label className="flex items-center gap-1.5 rounded-full border border-white/10 bg-white/[.03] px-3 py-2 text-[11px] font-bold text-slate-300"><Languages size={13} className="text-[#35dcb0]" /><span className="sr-only">Language</span><select aria-label="Language" value={activeLocale} onChange={(event) => changeLocale(event.target.value as Locale)} className="bg-transparent text-[11px] font-bold text-slate-300 outline-none"><option value="en" className="bg-[#151b28]">English</option><option value="es" className="bg-[#151b28]">Español</option><option value="pt" className="bg-[#151b28]">Português</option></select></label><button onClick={() => startLogin()} className="btn-press rounded-full px-4 py-2 text-[12px] font-bold text-slate-300 hover:text-white">{activeCopy.signIn}</button><PrimaryButton onClick={onJoin}>{activeCopy.join} <ArrowRight size={14} /></PrimaryButton></div><button className="rounded-lg p-2 text-slate-300 md:hidden" onClick={() => setMenuOpen(!menuOpen)} aria-label="Open menu">{menuOpen ? <X size={20} /> : <Menu size={20} />}</button></div>{menuOpen && <div className="border-t border-white/[.07] px-5 py-4 md:hidden"><div className="flex flex-col gap-4 text-sm font-semibold text-slate-300"><Link onClick={() => setMenuOpen(false)} href="/explore">{activeCopy.explore}</Link><Link onClick={() => setMenuOpen(false)} href="/messages">{activeCopy.messages}</Link><Link onClick={() => setMenuOpen(false)} href="/safety">{activeCopy.safety}</Link><Link onClick={() => setMenuOpen(false)} href="/account">{proCopy[activeLocale].account}</Link><label className="flex items-center gap-2 text-xs text-slate-300"><Languages size={14} className="text-[#35dcb0]" /><select aria-label="Language" value={activeLocale} onChange={(event) => changeLocale(event.target.value as Locale)} className="rounded-lg border border-white/10 bg-white/[.04] px-2 py-2 text-xs text-slate-300 outline-none"><option value="en" className="bg-[#151b28]">English</option><option value="es" className="bg-[#151b28]">Español</option><option value="pt" className="bg-[#151b28]">Português</option></select></label><button onClick={() => startLogin()} className="mt-1 text-left text-[#66a7ff]">{activeCopy.signIn}</button></div></div>}</header>;
}

